functions._atsState:
function _atsState() {
  if (!window._atsState_) {
    window._atsState_ = {
      templates: [],
      currentId: null,
      pickerOpen: false,
      promptValues: {},      // {name: selectedValue}
      detectedTags: [],      // {{name}} extractions
      logicBlocks: [],       // {{#if}} / {{else}} / {{/if}} tree
      lastDocText: "",       // cache for re-render without re-scan
      filterText: "",
      editingSchemaFor: null, // name of placeholder whose schema editor is open
      saveTimer: null,
    };
  }
  return window._atsState_;
}

// ── IDB helpers ─────────────────────────────────────────────────────

functions._atsLoadAll:
function _atsLoadAll() {
  if (!window.eli || !window.eli.storage) return Promise.resolve([]);
  return window.eli.storage.getAll("bd_templates").then(function (rows) {
    return (rows || []).filter(function (r) {
      return r && r.id && String(r.id).charAt(0) !== "_";
    });
  }).catch(function () { return []; });
}

functions._atsSaveRow:
function _atsSaveRow(tpl) {
  if (!tpl || !tpl.id) return Promise.reject(new Error("missing id"));
  tpl.lastUpdated = Date.now();
  return window.eli.storage.put("bd_templates", tpl);
}

functions._atsCurrent:
function _atsCurrent() {
  var st = _atsState();
  return st.templates.find(function (t) { return t.id === st.currentId; }) || null;
}

// ── Word interop ────────────────────────────────────────────────────
// Read the current doc body's text + OOXML. Used to detect tags and
// save the current Word state as a template.

functions._atsReadDoc:
function _atsReadDoc() {
  if (!window.eli || !window.eli.host || !window.eli.host.runRaw) {
    return Promise.reject(new Error("eli.host.runRaw unavailable"));
  }
  return window.eli.host.runRaw("ats:read_doc", function (context) {
    var body = context.document.body;
    body.load("text");
    var ooxml = body.getOoxml();
    return context.sync().then(function () {
      return { text: body.text || "", ooxml: ooxml.value || "" };
    });
  });
}

// Insert text at the current selection (cursor) in Word.

functions._atsInsertAtCursor:
function _atsInsertAtCursor(text) {
  return window.eli.host.runRaw("ats:insert_at_cursor", function (context) {
    var sel = context.document.getSelection();
    sel.insertText(text, Word.InsertLocation.replace);
    return context.sync();
  });
}

// Wrap the current selection in prefix/suffix (used for conditional blocks).

functions._atsWrapSelection:
function _atsWrapSelection(prefix, suffix) {
  return window.eli.host.runRaw("ats:wrap_sel", function (context) {
    var sel = context.document.getSelection();
    sel.load("text");
    return context.sync().then(function () {
      var inner = sel.text || "";
      sel.insertText(prefix + inner + suffix, Word.InsertLocation.replace);
      return context.sync();
    });
  });
}

// Apply curly-placeholder replacements: each `values` key is a bare
// placeholder name (e.g. "counterparty"). Searches for `{{name}}` in the
// doc and replaces every occurrence with the value. Skips empty values
// so the author can apply only the prompts they've answered.

functions._atsApplyCurlyReplacements:
function _atsApplyCurlyReplacements(values) {
  if (!values) return Promise.resolve(0);
  var entries = Object.keys(values).filter(function (k) {
    return values[k] != null && String(values[k]).length > 0;
  });
  if (!entries.length) return Promise.resolve(0);
  return window.eli.host.runRaw("ats:apply_curly_replacements", function (context) {
    var body = context.document.body;
    var pending = entries.map(function (name) {
      var pat = "{{" + name + "}}";
      var res = body.search(pat, { matchCase: true });
      res.load("items");
      return { pattern: pat, val: String(values[name]), results: res };
    });
    return context.sync().then(function () {
      var count = 0;
      pending.forEach(function (ps) {
        if (ps.results.items && ps.results.items.length) {
          ps.results.items.forEach(function (r) {
            r.insertText(ps.val, Word.InsertLocation.replace);
            count++;
          });
        }
      });
      return context.sync().then(function () { return count; });
    });
  });
}

// Snapshot the doc body's OOXML to IDB under STORE_CONFIG row id
// _template_studio_snapshot_<templateId>. Restore writes it back.

functions._atsSnapshot:
function _atsSnapshot() {
  var tpl = _atsCurrent();
  var id = tpl ? tpl.id : "_no_template";
  return _atsReadDoc().then(function (state) {
    return window.eli.storage.put("config", {
      key: "_template_studio_snapshot_" + id,
      ooxml: state.ooxml,
      capturedAt: Date.now(),
    }).then(function () { return true; });
  });
}

functions._atsRestore:
function _atsRestore() {
  var tpl = _atsCurrent();
  var id = tpl ? tpl.id : "_no_template";
  return window.eli.storage.get("config", "_template_studio_snapshot_" + id).then(function (row) {
    if (!row || !row.ooxml) {
      if (typeof showToast === "function") showToast("No snapshot to restore.", "warn");
      return false;
    }
    return window.eli.host.runRaw("ats:restore", function (context) {
      context.document.body.insertOoxml(row.ooxml, Word.InsertLocation.replace);
      return context.sync();
    }).then(function () {
      if (typeof showToast === "function") showToast("✓ Restored to snapshot", "ok");
      return true;
    });
  });
}

// Load the saved template's content into the Word doc (snapshot first).

functions._atsLoadIntoDoc:
function _atsLoadIntoDoc() {
  var tpl = _atsCurrent();
  if (!tpl) return Promise.resolve(false);
  if (typeof showToast === "function") showToast("⏳ Snapshotting + loading…", "info");
  return _atsSnapshot().then(function () {
    return window.eli.host.runRaw("ats:load_template", function (context) {
      var body = context.document.body;
      var s = String(tpl.content || "").trim();
      if (s.charAt(0) === "{") {
        try {
          var parsed = JSON.parse(s);
          if (parsed.body) {
            body.insertOoxml(parsed.body, Word.InsertLocation.replace);
            return context.sync();
          }
        } catch (e) { /* fall through */ }
      }
      body.insertText(s, Word.InsertLocation.replace);
      return context.sync();
    });
  }).then(function () {
    if (typeof showToast === "function") showToast("✓ Template loaded — edit in Word.", "ok");
    _atsDetectTagsLive();
    return true;
  }).catch(function (err) {
    if (typeof showToast === "function") showToast("Load failed: " + (err && err.message || "unknown"), "err");
    return false;
  });
}

// Capture the current Word doc body as the template's content. Saves
// to IDB. Storing as JSON envelope so headers/footers can be added
// later — currently captures body only.

functions._atsSaveFromDoc:
function _atsSaveFromDoc() {
  var tpl = _atsCurrent();
  if (!tpl) return Promise.resolve(false);
  if (tpl.locked) {
    if (typeof showToast === "function") showToast("Template is locked.", "warn");
    return Promise.resolve(false);
  }
  return _atsReadDoc().then(function (state) {
    tpl.content = JSON.stringify({ body: state.ooxml, sections: [] });
    return _atsSaveRow(tpl);
  }).then(function () {
    return _atsLoadAll();
  }).then(function (all) {
    _atsState().templates = all;
    _atsRenderAll();
    _atsSetSaveState("saved");
    if (typeof showToast === "function") showToast("✓ Saved Word doc → " + (tpl.name || tpl.id), "ok");
    setTimeout(function () { _atsSetSaveState(""); }, 2000);
    return true;
  }).catch(function (err) {
    if (typeof showToast === "function") showToast("Save failed: " + (err && err.message || "unknown"), "err");
    return false;
  });
}

// {{X}}-only placeholder extractor. Skips handlebars helpers
// (#if/else/each/etc.) so the prompt list only contains user-fillable
// variables. Returns dedup'd sorted array of inner names.

functions._atsExtractCurly:
function _atsExtractCurly(text) {
  var src = String(text || "");
  var found = {};
  var re = /\{\{\s*([^}|#\/\s][^}]*?)\s*\}\}/g;
  var m;
  while ((m = re.exec(src)) !== null) {
    var name = (m[1] || "").trim();
    if (!name) continue;
    if (/^(#?(if|each)|\/(if|each)|else)\b/i.test(name)) continue;
    if (/[\s{}]/.test(name)) continue;
    found[name] = true;
  }
  return Object.keys(found).sort();
}

// Ensure every detected {{name}} has a schema entry on the template.
// Existing entries are preserved (so type/options/label survive); new
// detected names get a default { type: "text" } entry. Returns whether
// the schema was mutated (caller saves to IDB).

functions._atsSyncPromptSchema:
function _atsSyncPromptSchema(tpl, detectedNames) {
  if (!tpl) return false;
  if (!Array.isArray(tpl.prompts)) tpl.prompts = [];
  var changed = false;
  var byName = {};
  tpl.prompts.forEach(function (p) { if (p && p.name) byName[p.name] = p; });
  detectedNames.forEach(function (n) {
    if (!byName[n]) {
      tpl.prompts.push({ name: n, label: n, type: "text", options: [], default: "" });
      changed = true;
    }
  });
  // Preserve schema entries even if the placeholder is currently absent
  // from the doc — author may be mid-edit, OR the placeholder was just
  // applied/replaced.
  return changed;
}

// Stack-based parse of {{#if X}} / {{else}} / {{/if}} (and {{#each X}} /
// {{/each}}). Returns array of root blocks (with nested children). Each
// block carries error info when opens/closes don't match.

functions._atsTraceLogicBlocks:
function _atsTraceLogicBlocks(text) {
  var src = String(text || "");
  var re = /\{\{\s*(#if|#each|else|\/if|\/each)\b([^}]*)\}\}/g;
  var tokens = [];
  var m;
  while ((m = re.exec(src)) !== null) {
    var kind = m[1];
    var arg = (m[2] || "").trim();
    var lineNo = src.slice(0, m.index).split(/\r?\n/).length;
    tokens.push({ kind: kind, arg: arg, pos: m.index, len: m[0].length, raw: m[0], line: lineNo });
  }
  var root = [];
  var stack = []; // [{block, type}] where type=if|each
  tokens.forEach(function (tok) {
    if (tok.kind === "#if" || tok.kind === "#each") {
      var block = {
        type: tok.kind === "#if" ? "if" : "each",
        condition: tok.arg,
        openPos: tok.pos,
        openLen: tok.len,
        openRaw: tok.raw,
        openLine: tok.line,
        elsePos: null,
        elseLine: null,
        closePos: null,
        closeLine: null,
        children: [],
        error: null,
      };
      if (stack.length) stack[stack.length - 1].block.children.push(block);
      else root.push(block);
      stack.push({ block: block, type: block.type });
    } else if (tok.kind === "else") {
      if (!stack.length || stack[stack.length - 1].type !== "if") {
        // Orphan else.
        root.push({ type: "if", condition: "", openPos: -1, error: "orphan {{else}} at line " + tok.line, elsePos: tok.pos, elseLine: tok.line, children: [] });
      } else {
        var top = stack[stack.length - 1].block;
        if (top.elsePos !== null) {
          top.error = (top.error || "") + " · duplicate {{else}} at line " + tok.line;
        } else {
          top.elsePos = tok.pos;
          top.elseLine = tok.line;
        }
      }
    } else if (tok.kind === "/if" || tok.kind === "/each") {
      var want = tok.kind === "/if" ? "if" : "each";
      if (!stack.length) {
        root.push({ type: want, condition: "", openPos: -1, error: "orphan {{" + tok.kind + "}} at line " + tok.line, closePos: tok.pos, closeLine: tok.line, children: [] });
        return;
      }
      var topEnt = stack[stack.length - 1];
      if (topEnt.type !== want) {
        topEnt.block.error = (topEnt.block.error || "") + " · expected {{/" + topEnt.type + "}} but got {{" + tok.kind + "}} at line " + tok.line;
      }
      topEnt.block.closePos = tok.pos;
      topEnt.block.closeLine = tok.line;
      stack.pop();
    }
  });
  // Anything still on the stack is an unclosed open.
  while (stack.length) {
    var unfin = stack.pop().block;
    unfin.error = (unfin.error || "") + " · unclosed (no matching {{/" + unfin.type + "}})";
  }
  return root;
}

// Scan current Word doc body. Extracts {{name}} placeholders, traces
// {{#if}} blocks, and syncs the schema for any newly-detected names
// onto the active template. Auto-saves schema additions so picking up
// a new placeholder in Word immediately gives it a schema entry.

functions._atsDetectTagsLive:
function _atsDetectTagsLive() {
  return _atsReadDoc().then(function (state) {
    var st = _atsState();
    st.lastDocText = state.text || "";

    var names = _atsExtractCurly(st.lastDocText);
    st.detectedTags = names;
    st.logicBlocks = _atsTraceLogicBlocks(st.lastDocText);

    // Merge into the active template's prompt schema (preserves type/
    // options/label of existing entries; adds defaults for new names).
    var tpl = _atsCurrent();
    if (tpl && !tpl.locked) {
      var changed = _atsSyncPromptSchema(tpl, names);
      if (changed) {
        _atsSaveRow(tpl).catch(function () {});
      }
    }

    _atsRenderDetected();
    _atsRenderPrompts();
    _atsRenderLogicTree();
    return { tags: names, blocks: st.logicBlocks };
  }).catch(function () { return { tags: [], blocks: [] }; });
}

// Locate a substring in the Word doc and select/scroll-into-view.
// Used by click-to-jump on logic blocks + BD prompts.

functions._atsScrollToInDoc:
function _atsScrollToInDoc(needle) {
  if (!needle) return;
  var s = String(needle).trim();
  if (!s) return;
  // Word's body.search has a 250-char limit and dislikes some special
  // characters — trim to a safe snippet.
  var snippet = s.slice(0, 200).replace(/[\r\n\t]+/g, " ");
  return window.eli.host.runRaw("ats:scroll_to", function (context) {
    var r = context.document.body.search(snippet, { matchCase: false, ignorePunct: true, ignoreSpace: true });
    r.load("items");
    return context.sync().then(function () {
      if (!r.items || !r.items.length) return false;
      try { r.items[0].select(); r.items[0].scrollIntoView(); } catch (e) {}
      return context.sync().then(function () { return true; });
    });
  }).catch(function () { return false; });
}

// ── Save state pill ─────────────────────────────────────────────────

functions._atsSetSaveState:
function _atsSetSaveState(state) {
  var el = document.getElementById("atsSaveState");
  if (!el) return;
  el.classList.remove("_ats_saving", "_ats_saved", "_ats_dirty");
  if (state === "saving") { el.textContent = "Saving…"; el.classList.add("_ats_saving"); }
  else if (state === "saved") { el.textContent = "✓ Saved"; el.classList.add("_ats_saved"); }
  else if (state === "dirty") { el.textContent = "Unsaved"; el.classList.add("_ats_dirty"); }
  else { el.textContent = ""; }
}

// ── Renderers ──────────────────────────────────────────────────────

functions._atsRenderCurrent:
function _atsRenderCurrent() {
  var bar = document.getElementById("atsCurrent");
  if (!bar) return;
  var tpl = _atsCurrent();
  if (!tpl) {
    bar.innerHTML =
      '<div class="_ats_current_left">' +
        '<div class="_ats_current_label">Active Template</div>' +
        '<div class="_ats_current_name" style="color:#94a3b8;">(none selected)</div>' +
      '</div>' +
      '<div class="_ats_current_right">' +
        '<button class="_ats_btn _ats_btn_gold" id="atsOpenPicker">📂 Pick template</button>' +
      '</div>';
    document.getElementById("atsOpenPicker").onclick = function () {
      _atsState().pickerOpen = true;
      _atsRenderPicker();
    };
    return;
  }
  var status = tpl.status || "active";
  var size = String(tpl.content || "").length;
  bar.innerHTML =
    '<div class="_ats_current_left">' +
      '<div class="_ats_current_label">Active Template</div>' +
      '<div class="_ats_current_name">' + _atsEsc(tpl.name || tpl.id) + '</div>' +
      '<div class="_ats_current_meta">' +
        '<span class="_ats_pill _ats_pill_' + status + '">' + status + '</span>' +
        (tpl.locked ? '<span class="_ats_pill _ats_pill_archived">🔒 locked</span>' : '') +
        '<span>' + _atsEsc(tpl.agreementType || "—") + '</span>' +
        '<span>· ' + Math.round(size / 1024) + ' KB</span>' +
      '</div>' +
    '</div>' +
    '<div class="_ats_current_right">' +
      '<button class="_ats_btn _ats_btn_ghost" id="atsSwitchTpl">↔ Switch</button>' +
    '</div>';
  document.getElementById("atsSwitchTpl").onclick = function () {
    var st = _atsState();
    st.pickerOpen = !st.pickerOpen;
    _atsRenderPicker();
  };
}

functions._atsRenderPicker:
function _atsRenderPicker() {
  var box = document.getElementById("atsPicker");
  if (!box) return;
  var st = _atsState();
  if (st.pickerOpen) box.classList.add("_ats_picker_open");
  else box.classList.remove("_ats_picker_open");
  var bodyEl = document.getElementById("atsPickerBody");
  if (!bodyEl) return;
  var f = (st.filterText || "").toLowerCase();
  var rows = st.templates.filter(function (t) {
    if (!f) return true;
    var hay = ((t.name || "") + " " + (t.agreementType || "") + " " + (t.id || "")).toLowerCase();
    return hay.indexOf(f) !== -1;
  });
  var listHtml = rows.length
    ? rows.map(function (t) {
        var active = (t.id === st.currentId) ? " _ats_active" : "";
        var status = t.status || "active";
        return '<div class="_ats_picker_card' + active + '" data-ats-id="' + _atsEsc(t.id) + '">' +
          '<div class="_ats_picker_card_name">' + _atsEsc(t.name || t.id) + '</div>' +
          '<div class="_ats_picker_card_meta">' +
            '<span class="_ats_pill _ats_pill_' + status + '">' + status + '</span> ' +
            _atsEsc(t.agreementType || "—") +
            ' · ' + Math.round(String(t.content || "").length / 1024) + ' KB' +
          '</div>' +
        '</div>';
      }).join("")
    : '<div style="padding:20px; text-align:center; font-size:10px; color:#94a3b8;">No templates' + (f ? ' match.' : '. Click + New below to create one.') + '</div>';
  bodyEl.innerHTML =
    '<div class="_ats_picker_search">' +
      '<input id="atsPickerSearch" type="text" placeholder="Filter templates…" value="' + _atsEsc(st.filterText) + '">' +
    '</div>' +
    '<div class="_ats_picker_list">' + listHtml + '</div>' +
    '<div class="_ats_picker_footer">' +
      '<button class="_ats_btn _ats_btn_gold" id="atsNew">+ New</button>' +
      '<button class="_ats_btn _ats_btn_ghost" id="atsDuplicate">📋 Duplicate</button>' +
      '<button class="_ats_btn _ats_btn_ghost" id="atsImport">⬆ Import</button>' +
    '</div>';
  document.getElementById("atsPickerSearch").oninput = function () {
    _atsState().filterText = this.value;
    _atsRenderPicker();
  };
  bodyEl.querySelectorAll("[data-ats-id]").forEach(function (c) {
    c.onclick = function () {
      _atsState().currentId = c.getAttribute("data-ats-id");
      _atsState().pickerOpen = false;
      _atsRenderAll();
    };
  });
  document.getElementById("atsNew").onclick = _atsActionNew;
  document.getElementById("atsDuplicate").onclick = _atsActionDuplicate;
  document.getElementById("atsImport").onclick = _atsActionImport;
}

functions._atsRenderDetected:
function _atsRenderDetected() {
  var box = document.getElementById("atsDetectedBody");
  if (!box) return;
  var tags = _atsState().detectedTags || [];
  if (!tags.length) {
    box.innerHTML = '<span class="_ats_detected_empty">No tags found yet. Insert one with the picker below, then click 🔄.</span>';
  } else {
    box.innerHTML = tags.map(function (t) {
      return '<span class="_ats_quick_tag" data-ats-quicktag="' + _atsEsc(t) + '">' + _atsEsc(t) + '</span>';
    }).join("");
    box.querySelectorAll("[data-ats-quicktag]").forEach(function (chip) {
      chip.onclick = function () {
        // Click a detected tag → focus its mock-value input.
        var v = chip.getAttribute("data-ats-quicktag");
        var inp = document.querySelector('[data-ats-mock="' + v + '"]');
        if (inp) inp.focus();
      };
    });
  }
  var countEl = document.getElementById("atsDetectedCount");
  if (countEl) countEl.textContent = tags.length;
}

// Per-placeholder type-aware input. Each `{{name}}` in the doc has an
// entry in tpl.prompts[]: { name, label, type, options, default }.
// Each row shows the configured input, ⚙ opens an inline schema editor
// (label / type / options / default), and clicking the name chip jumps
// to the first occurrence in Word. Changes write to state.promptValues
// and are applied to the doc on the "Apply" button (or via Enter on a
// dropdown).

functions._atsRenderPrompts:
function _atsRenderPrompts() {
  var box = document.getElementById("atsPromptList");
  if (!box) return;
  var st = _atsState();
  var tpl = _atsCurrent();
  var schema = (tpl && Array.isArray(tpl.prompts)) ? tpl.prompts : [];
  // Only render entries that are in the schema. (Detection adds them
  // automatically on scan — see _atsSyncPromptSchema.)
  if (!schema.length) {
    box.innerHTML = '<div style="font-size:10px; color:#94a3b8;">No <code>{{name}}</code> placeholders found. Add one with the picker above, then click 🔄.</div>';
    return;
  }
  box.innerHTML = schema.map(function (p) {
    var name = p.name;
    var label = p.label || p.name;
    var type = p.type || "text";
    var def = p.default || "";
    var v = (st.promptValues[name] != null) ? st.promptValues[name] : def;
    var isEditing = (st.editingSchemaFor === name);
    var inputHtml = "";
    if (type === "dropdown") {
      var opts = (p.options || []).map(function (o) {
        var sel = (String(v) === String(o)) ? " selected" : "";
        return '<option value="' + _atsEsc(o) + '"' + sel + '>' + _atsEsc(o) + '</option>';
      }).join("");
      inputHtml =
        '<select class="_ats_select" data-ats-prompt="' + _atsEsc(name) + '">' +
          '<option value="">— pick —</option>' + opts +
        '</select>';
    } else if (type === "number") {
      inputHtml = '<input class="_ats_input" type="number" data-ats-prompt="' + _atsEsc(name) + '" value="' + _atsEsc(v) + '" placeholder="' + _atsEsc(label) + '">';
    } else if (type === "date") {
      inputHtml = '<input class="_ats_input" type="date" data-ats-prompt="' + _atsEsc(name) + '" value="' + _atsEsc(v) + '">';
    } else if (type === "textarea") {
      inputHtml = '<textarea class="_ats_input _ats_textarea" data-ats-prompt="' + _atsEsc(name) + '" rows="3" placeholder="' + _atsEsc(label) + '">' + _atsEsc(v) + '</textarea>';
    } else {
      inputHtml = '<input class="_ats_input" type="text" data-ats-prompt="' + _atsEsc(name) + '" value="' + _atsEsc(v) + '" placeholder="' + _atsEsc(label) + '">';
    }
    var typeBadge = '<span class="_ats_promptrow_type">' + _atsEsc(type) + '</span>';
    return '<div class="_ats_promptrow">' +
      '<div class="_ats_promptrow_head">' +
        '<button class="_ats_promptrow_chip" data-ats-promptjump="' + _atsEsc(name) + '" title="Jump to {{' + _atsEsc(name) + '}} in Word">{{' + _atsEsc(name) + '}}</button>' +
        '<span class="_ats_promptrow_label">' + _atsEsc(label) + '</span>' +
        typeBadge +
        '<button class="_ats_btn _ats_btn_ghost _ats_promptrow_cog" data-ats-promptedit="' + _atsEsc(name) + '" title="Edit schema">⚙</button>' +
      '</div>' +
      inputHtml +
      (isEditing ? _atsRenderSchemaEditor(p) : "") +
      '</div>';
  }).join("");
  // Value inputs → write to state, debounced re-render is overkill; we
  // just need promptValues live so Apply works.
  box.querySelectorAll("[data-ats-prompt]").forEach(function (inp) {
    var name = inp.getAttribute("data-ats-prompt");
    var handler = function () { _atsState().promptValues[name] = inp.value; };
    inp.oninput = handler;
    inp.onchange = handler;
  });
  box.querySelectorAll("[data-ats-promptjump]").forEach(function (b) {
    b.onclick = function () {
      var n = b.getAttribute("data-ats-promptjump");
      _atsScrollToInDoc("{{" + n + "}}");
    };
  });
  box.querySelectorAll("[data-ats-promptedit]").forEach(function (b) {
    b.onclick = function () {
      var n = b.getAttribute("data-ats-promptedit");
      var s = _atsState();
      s.editingSchemaFor = (s.editingSchemaFor === n) ? null : n;
      _atsRenderPrompts();
    };
  });
  // Wire schema-editor controls (rendered inline when editingSchemaFor matches).
  box.querySelectorAll("[data-ats-schema-field]").forEach(function (inp) {
    inp.onchange = _atsHandleSchemaFieldChange;
    inp.oninput = _atsHandleSchemaFieldChange;
  });
  box.querySelectorAll("[data-ats-schema-action]").forEach(function (btn) {
    btn.onclick = function () { _atsHandleSchemaAction(btn.getAttribute("data-ats-schema-action"), btn.getAttribute("data-ats-schema-name")); };
  });
}

// Inline schema editor rendered under a prompt row. Lets the admin pick
// type, edit label, set default, and (for dropdowns) edit options.

functions._atsRenderSchemaEditor:
function _atsRenderSchemaEditor(p) {
  var types = ["text", "dropdown", "number", "date", "textarea"];
  var typeOpts = types.map(function (t) {
    return '<option value="' + t + '"' + (((p.type || "text") === t) ? " selected" : "") + '>' + t + '</option>';
  }).join("");
  var optionsHtml = "";
  if ((p.type || "text") === "dropdown") {
    optionsHtml =
      '<div class="_ats_schema_field">' +
        '<div class="_ats_field_label">Options (one per line)</div>' +
        '<textarea class="_ats_input _ats_textarea" rows="3" data-ats-schema-field="options" data-ats-schema-name="' + _atsEsc(p.name) + '">' +
          _atsEsc((p.options || []).join("\n")) +
        '</textarea>' +
      '</div>';
  }
  return '<div class="_ats_schema_editor">' +
    '<div class="_ats_schema_editor_head">⚙ Schema for <code>{{' + _atsEsc(p.name) + '}}</code></div>' +
    '<div class="_ats_schema_grid">' +
      '<div class="_ats_schema_field">' +
        '<div class="_ats_field_label">Label</div>' +
        '<input class="_ats_input" type="text" data-ats-schema-field="label" data-ats-schema-name="' + _atsEsc(p.name) + '" value="' + _atsEsc(p.label || p.name) + '">' +
      '</div>' +
      '<div class="_ats_schema_field">' +
        '<div class="_ats_field_label">Type</div>' +
        '<select class="_ats_select" data-ats-schema-field="type" data-ats-schema-name="' + _atsEsc(p.name) + '">' + typeOpts + '</select>' +
      '</div>' +
    '</div>' +
    '<div class="_ats_schema_field">' +
      '<div class="_ats_field_label">Default value</div>' +
      '<input class="_ats_input" type="text" data-ats-schema-field="default" data-ats-schema-name="' + _atsEsc(p.name) + '" value="' + _atsEsc(p.default || "") + '">' +
    '</div>' +
    optionsHtml +
    '<div style="margin-top:6px; display:flex; gap:4px;">' +
      '<button class="_ats_btn _ats_btn_ghost" data-ats-schema-action="close" data-ats-schema-name="' + _atsEsc(p.name) + '">Done</button>' +
      '<button class="_ats_btn _ats_btn_danger" data-ats-schema-action="remove" data-ats-schema-name="' + _atsEsc(p.name) + '" title="Remove this from the schema (does not remove {{tag}} from the doc)">Remove from schema</button>' +
    '</div>' +
  '</div>';
}

functions._atsHandleSchemaFieldChange:
function _atsHandleSchemaFieldChange(ev) {
  var el = ev.currentTarget || ev.target;
  var field = el.getAttribute("data-ats-schema-field");
  var name = el.getAttribute("data-ats-schema-name");
  var tpl = _atsCurrent();
  if (!tpl || !Array.isArray(tpl.prompts)) return;
  var p = tpl.prompts.find(function (x) { return x.name === name; });
  if (!p) return;
  if (field === "label") p.label = el.value;
  else if (field === "type") {
    p.type = el.value;
    if (p.type !== "dropdown") p.options = [];
  } else if (field === "default") p.default = el.value;
  else if (field === "options") {
    p.options = el.value.split(/\r?\n/).map(function (s) { return s.trim(); }).filter(Boolean);
  }
  _atsSetSaveState("saving");
  _atsSaveRow(tpl).then(function () {
    _atsSetSaveState("saved");
    setTimeout(function () { _atsSetSaveState(""); }, 1200);
    // Re-render so type change swaps the input control.
    if (field === "type" || field === "options") _atsRenderPrompts();
  }).catch(function () { _atsSetSaveState("dirty"); });
}

functions._atsHandleSchemaAction:
function _atsHandleSchemaAction(action, name) {
  var s = _atsState();
  if (action === "close") {
    s.editingSchemaFor = null;
    _atsRenderPrompts();
    return;
  }
  if (action === "remove") {
    var tpl = _atsCurrent();
    if (!tpl || !Array.isArray(tpl.prompts)) return;
    tpl.prompts = tpl.prompts.filter(function (x) { return x.name !== name; });
    s.editingSchemaFor = null;
    _atsSaveRow(tpl).then(function () {
      _atsRenderPrompts();
      if (typeof showToast === "function") showToast("Removed " + name + " from schema", "info");
    });
  }
}

// Logic block tree — renders the {{#if}} / {{else}} / {{/if}} structure
// with error markers, line numbers, and click-to-jump.

functions._atsRenderLogicTree:
function _atsRenderLogicTree() {
  var box = document.getElementById("atsLogicTree");
  if (!box) return;
  var blocks = _atsState().logicBlocks || [];
  if (!blocks.length) {
    box.innerHTML = '<div style="font-size:10px; color:#94a3b8;">No conditional blocks found. Wrap a selection with the form above.</div>';
    return;
  }
  function renderBlock(b, depth) {
    var icon = b.type === "each" ? "🔁" : "🔀";
    var hasElse = b.elsePos !== null && b.elseLine !== null;
    var closed = b.closePos !== null;
    var errCls = b.error ? " _ats_logic_err" : (closed ? "" : " _ats_logic_warn");
    var pad = (depth * 14) + "px";
    var openLine = b.openLine != null ? b.openLine : "?";
    var closeLine = b.closeLine != null ? b.closeLine : "—";
    var condLabel = b.condition || "(no condition)";
    var html =
      '<div class="_ats_logic_block' + errCls + '" style="margin-left:' + pad + ';">' +
        '<div class="_ats_logic_block_head">' +
          '<span class="_ats_logic_block_kind">' + icon + ' ' + b.type + '</span>' +
          '<button class="_ats_logic_block_cond" data-ats-trace-jump="' + _atsEsc(b.openRaw || ("{{#" + b.type + " " + condLabel + "}}")) + '" title="Jump to opener in Word">' +
            _atsEsc(condLabel) + '</button>' +
          '<span class="_ats_logic_block_lines">L' + openLine + (hasElse ? '→' + b.elseLine : '') + '→' + closeLine + '</span>' +
        '</div>' +
        (b.error ? '<div class="_ats_logic_block_err">⚠ ' + _atsEsc(b.error) + '</div>' : '') +
        (b.children && b.children.length
          ? '<div class="_ats_logic_children">' + b.children.map(function (c) { return renderBlock(c, depth + 1); }).join("") + '</div>'
          : '') +
      '</div>';
    return html;
  }
  box.innerHTML = blocks.map(function (b) { return renderBlock(b, 0); }).join("");
  box.querySelectorAll("[data-ats-trace-jump]").forEach(function (btn) {
    btn.onclick = function () {
      _atsScrollToInDoc(btn.getAttribute("data-ats-trace-jump"));
    };
  });

  // Update header summary count.
  var errCount = 0, total = 0;
  function walk(arr) {
    arr.forEach(function (b) {
      total++;
      if (b.error || b.closePos === null) errCount++;
      if (b.children) walk(b.children);
    });
  }
  walk(blocks);
  var countEl = document.getElementById("atsLogicCount");
  if (countEl) countEl.textContent = total + (errCount ? " · " + errCount + " ⚠" : "");
}

functions._atsRenderMetadata:
function _atsRenderMetadata() {
  var box = document.getElementById("atsMetadataBody");
  if (!box) return;
  var tpl = _atsCurrent();
  if (!tpl) { box.innerHTML = ""; return; }
  var statusOpts = ["active", "draft", "archived"].map(function (s) {
    return '<option value="' + s + '"' + (((tpl.status || "active") === s) ? " selected" : "") + '>' + s + '</option>';
  }).join("");
  box.innerHTML =
    '<div class="_ats_metaedit">' +
      '<div>' +
        '<div class="_ats_field_label">Name</div>' +
        '<input id="atsFieldName" class="_ats_input" type="text" value="' + _atsEsc(tpl.name || "") + '">' +
      '</div>' +
      '<div>' +
        '<div class="_ats_field_label">Status</div>' +
        '<select id="atsFieldStatus" class="_ats_select">' + statusOpts + '</select>' +
      '</div>' +
    '</div>' +
    '<div style="margin-top:6px;">' +
      '<div class="_ats_field_label">Agreement type</div>' +
      '<input id="atsFieldType" class="_ats_input" type="text" value="' + _atsEsc(tpl.agreementType || "") + '" placeholder="e.g. Non-Disclosure Agreement">' +
    '</div>' +
    '<div style="margin-top:10px; display:flex; gap:4px;">' +
      '<button class="_ats_btn _ats_btn_success" id="atsMetaSave" style="flex:1;">💾 Save metadata</button>' +
      '<button class="_ats_btn _ats_btn_ghost" id="atsLock">' + (tpl.locked ? "🔓 Unlock" : "🔒 Lock") + '</button>' +
      '<button class="_ats_btn _ats_btn_ghost" id="atsExport">⬇</button>' +
      '<button class="_ats_btn _ats_btn_danger" id="atsDelete">🗑</button>' +
    '</div>';
  document.getElementById("atsMetaSave").onclick = function () {
    var t = _atsCurrent();
    if (!t) return;
    t.name = document.getElementById("atsFieldName").value || t.name;
    t.agreementType = document.getElementById("atsFieldType").value || t.agreementType;
    t.status = document.getElementById("atsFieldStatus").value || t.status;
    _atsSetSaveState("saving");
    _atsSaveRow(t).then(function () { return _atsLoadAll(); }).then(function (all) {
      _atsState().templates = all;
      _atsRenderAll();
      _atsSetSaveState("saved");
      setTimeout(function () { _atsSetSaveState(""); }, 1500);
    });
  };
  document.getElementById("atsLock").onclick = _atsActionLock;
  document.getElementById("atsExport").onclick = _atsActionExport;
  document.getElementById("atsDelete").onclick = _atsActionDelete;
}

functions._atsRenderAll:
function _atsRenderAll() {
  var hasTpl = !!_atsCurrent();
  var body = document.getElementById("atsBody");
  if (!body) return;
  if (!hasTpl) {
    body.innerHTML =
      '<div class="_ats_empty_state">' +
        '<div class="_ats_empty_icon">📋</div>' +
        '<div class="_ats_empty_title">No template selected</div>' +
        '<div class="_ats_empty_sub">Open the picker above to load one, or create a new template to start.</div>' +
      '</div>';
    _atsRenderCurrent();
    return;
  }
  body.innerHTML =
    // Word ↔ Template
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">📝 Word ↔ Template</div>' +
      '</div>' +
      '<div class="_ats_section_hint">' +
        'Edit the template <b>in Word</b>. Load pulls the saved content into the doc (snapshots first). Save captures the current doc body into this template.' +
      '</div>' +
      '<div class="_ats_grid_2">' +
        '<button class="_ats_btn _ats_btn_primary" id="atsLoadInto">📥 Load into Word</button>' +
        '<button class="_ats_btn _ats_btn_success" id="atsSaveFrom">💾 Save Word doc</button>' +
      '</div>' +
    '</div>' +

    // Test safety
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">🧪 Test safety</div>' +
      '</div>' +
      '<div class="_ats_grid_2">' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsSnap">📸 Snapshot doc</button>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsRestore">↩ Restore</button>' +
      '</div>' +
      '<div class="_ats_section_hint" style="margin-top:6px; margin-bottom:0;">' +
        'Snapshot the doc body before risky edits. Restore reverts back.' +
      '</div>' +
    '</div>' +

    // Logic insertion at cursor (Word)
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">➕ Insert logic at cursor</div>' +
      '</div>' +
      '<div class="_ats_section_hint">Drop placeholders and conditional blocks where the cursor is in Word.</div>' +
      '<div class="_ats_logic_row">' +
        '<input id="atsPlaceholderInput" type="text" placeholder="placeholderName" autocomplete="off">' +
        '<button class="_ats_btn _ats_btn_primary" id="atsInsertPh">+ Placeholder</button>' +
      '</div>' +
      '<div class="_ats_logic_row">' +
        '<input id="atsConditionInput" type="text" placeholder="condition (e.g. hasIndemnity)" autocomplete="off">' +
        '<button class="_ats_btn _ats_btn_primary" id="atsWrapCond">↻ Wrap selection if</button>' +
      '</div>' +
      '<div class="_ats_grid_2" style="margin-top:6px;">' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsInsertElse">+ {{else}}</button>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsInsertEnd">+ {{/if}}</button>' +
      '</div>' +
    '</div>' +

    // Detected tags (from live Word doc)
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">🔍 Detected in doc <span class="_ats_detected_count" id="atsDetectedCount">0</span></div>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsRefreshTags">🔄</button>' +
      '</div>' +
      '<div class="_ats_detected" id="atsDetectedBody"></div>' +
    '</div>' +

    // Logic block tracer — {{#if}} / {{else}} / {{/if}} structure with errors.
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">🌳 Logic blocks <span class="_ats_detected_count" id="atsLogicCount">0</span></div>' +
      '</div>' +
      '<div class="_ats_section_hint">Traced from <code>{{#if X}}</code> / <code>{{else}}</code> / <code>{{/if}}</code> (and <code>{{#each}}</code>) in the doc. Click a condition to jump to it. Red blocks have errors (unmatched/duplicated).</div>' +
      '<div id="atsLogicTree" class="_ats_logic_tree"></div>' +
    '</div>' +

    // Template prompts — every {{name}} gets a typed input. Per-prompt
    // schema editor (label / type / options / default) opens inline.
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">🎯 Template prompts</div>' +
      '</div>' +
      '<div class="_ats_section_hint">Every <code>{{name}}</code> in the doc gets a row. Click ⚙ to set the type (text / dropdown / number / date / textarea). Fill values, then apply to substitute into the Word doc. Click <code>{{name}}</code> to jump.</div>' +
      '<div id="atsPromptList" class="_ats_promptlist"></div>' +
      '<div style="margin-top:8px;">' +
        '<button class="_ats_btn _ats_btn_primary" id="atsApplyPrompts" style="width:100%;">⚡ Apply prompt values to Word</button>' +
      '</div>' +
    '</div>' +

    // Metadata (collapsible-feeling at the bottom — small, edit-when-needed)
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">📌 Metadata</div>' +
      '</div>' +
      '<div id="atsMetadataBody"></div>' +
