          '<div class="_ats_header_title">📋 Template Studio</div>' +
          '<div class="_ats_header_sub">Word is the editor. This panel helps add logic + test things.</div>' +
        '</div>' +
        '<div id="atsSaveState" class="_ats_savestate"></div>' +
      '</div>' +

      // Current template bar
      '<div class="_ats_current" id="atsCurrent"></div>' +

      // Collapsible picker
      '<div class="_ats_picker" id="atsPicker">' +
        '<div class="_ats_picker_head" id="atsPickerHead">' +
          '<span class="_ats_picker_title">📂 All templates</span>' +
          '<span style="font-size:9px; color:#94a3b8;" id="atsPickerCount">—</span>' +
          '<span class="_ats_picker_caret">▶</span>' +
        '</div>' +
        '<div class="_ats_picker_body" id="atsPickerBody"></div>' +
      '</div>' +

      // Main body (workflow sections)
      '<div id="atsBody"></div>' +
    '</div>';

  // Picker head toggles open/closed
  document.getElementById("atsPickerHead").onclick = function () {
    var st = _atsState();
    st.pickerOpen = !st.pickerOpen;
    _atsRenderPicker();
  };

  _atsLoadAll().then(function (all) {
    var st = _atsState();
    st.templates = all;
    // Auto-select the most recently-updated template if nothing's selected.
    if (!st.currentId && all.length) {
      var sorted = all.slice().sort(function (a, b) { return (b.lastUpdated || 0) - (a.lastUpdated || 0); });
      st.currentId = sorted[0].id;
    }
    document.getElementById("atsPickerCount").textContent = all.length + " template" + (all.length === 1 ? "" : "s");
    _atsRenderAll();
    _atsRenderPicker();
    // Initial tag scan (best-effort — fails silently if no doc is ready).
    _atsDetectTagsLive();
  });
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedTemplateStudio"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showAdminTemplateStudio !== "function") {
      eli.log.event("tool", "admin_template_studio_fn_missing", {});
      if (typeof showToast === "function") showToast("Template Studio failed to load", "err");
      return;
    }
    try { window.showAdminTemplateStudio(); }
    catch (e) {
      eli.log.event("tool", "admin_template_studio_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  if (typeof window._ebEsc !== "function") {
    window._ebEsc = function (s) {
      return String(s == null ? "" : s)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    };
  }

  eli.register({
    tile: { app_admin_template_studio: _show },
    admin_template_studio: { open: _show },
  });

  eli.log.event("tool", "admin_template_studio_initialized", {});
}

jsonTools.css:
/* admin_template_studio v2 — compact companion panel. Word doc is the
   editor; this tool helps add logic + test things. Single column, fits
   the Word taskpane. Class prefix `_ats_`. */

._ats_root {
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  display: flex; flex-direction: column;
  min-height: 100vh;
}

._ats_header {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fff;
  padding: 14px 18px;
  border-bottom: 3px solid #c9a227;
  display: flex; justify-content: space-between; align-items: center;
  flex: 0 0 auto;
}
._ats_header_left { min-width: 0; }
._ats_header_eyebrow {
  font: 800 8px/1 Inter, sans-serif; letter-spacing: 1.3px;
  text-transform: uppercase; color: #c9a227;
}
._ats_header_title { font: 800 17px/1.1 "Book Antiqua", Georgia, serif; margin: 2px 0 0 0; }
._ats_header_sub { font-size: 10px; color: rgba(255,255,255,0.65); margin-top: 2px; line-height: 1.4; }
._ats_savestate {
  font-size: 9px; font-weight: 700;
  padding: 3px 8px; border-radius: 100px;
  background: rgba(255, 255, 255, 0.12);
  color: rgba(255, 255, 255, 0.85);
  letter-spacing: 0.5px; text-transform: uppercase;
}
._ats_saving { background: rgba(201,162,39,0.25); color: #ffd76b; }
._ats_saved  { background: rgba(34,197,94,0.15); color: #6ee7b7; }
._ats_dirty  { background: rgba(245,158,11,0.18); color: #fcd34d; }

/* ─── Current-template bar (always visible) ──────────────────────── */
._ats_current {
  display: grid; grid-template-columns: 1fr auto;
  gap: 10px; align-items: center;
  background: #fff;
  padding: 10px 14px;
  border-bottom: 1px solid #e2e8f0;
}
._ats_current_left { min-width: 0; }
._ats_current_label {
  font: 800 8px/1 Inter, sans-serif; letter-spacing: 0.6px;
  text-transform: uppercase; color: #64748b;
}
._ats_current_name {
  font: 800 14px/1.2 Inter, sans-serif; color: #0f172a;
  margin-top: 3px; overflow: hidden; text-overflow: ellipsis;
  white-space: nowrap;
}
._ats_current_meta {
  font-size: 10px; color: #64748b; margin-top: 2px;
  display: flex; gap: 6px; align-items: center;
}
._ats_pill {
  font: 800 8px/1 Inter, sans-serif; letter-spacing: 0.5px;
  padding: 2px 6px; text-transform: uppercase;
}
._ats_pill_active   { background: #dcfce7; color: #166534; }
._ats_pill_draft    { background: #fef3c7; color: #92400e; }
._ats_pill_archived { background: #f1f5f9; color: #64748b; }
._ats_current_right { display: flex; gap: 4px; }

._ats_btn {
  padding: 6px 10px; font: 800 9px/1 Inter, sans-serif;
  letter-spacing: 0.4px; text-transform: uppercase;
  border: none; cursor: pointer;
  transition: all 0.15s;
  display: inline-flex; align-items: center; gap: 4px;
}
._ats_btn:disabled { opacity: 0.5; cursor: progress; }
._ats_btn_primary { background: #1565c0; color: #fff; }
._ats_btn_primary:hover:not(:disabled) { background: #0d47a1; }
._ats_btn_gold { background: #c9a227; color: #0d1b2a; }
._ats_btn_gold:hover:not(:disabled) { filter: brightness(0.95); }
._ats_btn_ghost { background: #fff; color: #475569; border: 1px solid #cbd5e1; }
._ats_btn_ghost:hover:not(:disabled) { color: #1565c0; border-color: #1565c0; }
._ats_btn_danger { background: #fff; color: #b91c1c; border: 1px solid #fca5a5; }
._ats_btn_danger:hover:not(:disabled) { background: #fef2f2; }
._ats_btn_success { background: #16a34a; color: #fff; }
._ats_btn_success:hover:not(:disabled) { background: #15803d; }

/* ─── Picker (collapsible) ────────────────────────────────────────── */
._ats_picker {
  background: #fff; border-bottom: 1px solid #e2e8f0;
}
._ats_picker_head {
  display: grid; grid-template-columns: 1fr auto auto;
  gap: 8px; align-items: center;
  padding: 8px 14px; cursor: pointer;
  border-bottom: 1px solid transparent;
  transition: background 0.15s;
}
._ats_picker_head:hover { background: #f8fafc; }
._ats_picker_open ._ats_picker_head { border-bottom-color: #f1f5f9; }
._ats_picker_caret {
  font-size: 10px; color: #94a3b8;
  transition: transform 0.2s;
}
._ats_picker_open ._ats_picker_caret { transform: rotate(90deg); }
._ats_picker_title {
  font: 800 9px/1 Inter, sans-serif; letter-spacing: 0.6px;
  text-transform: uppercase; color: #475569;
}
._ats_picker_body { display: none; padding: 10px 14px; }
._ats_picker_open ._ats_picker_body { display: block; }

._ats_picker_search {
  position: relative; margin-bottom: 8px;
}
._ats_picker_search input {
  width: 100%; padding: 6px 10px 6px 28px;
  font-size: 11px; border: 1px solid #cbd5e1;
  outline: none; box-sizing: border-box;
}
._ats_picker_search input:focus { border-color: #1565c0; }
._ats_picker_search::before {
  content: "🔍"; position: absolute; left: 8px;
  top: 50%; transform: translateY(-50%);
  font-size: 11px; pointer-events: none;
}

._ats_picker_list { max-height: 220px; overflow-y: auto; }
._ats_picker_card {
  padding: 7px 10px; margin-bottom: 3px;
  border: 1px solid #e2e8f0; background: #fff;
  cursor: pointer; transition: all 0.15s;
}
._ats_picker_card:hover { border-color: #cbd5e1; background: #f8fafc; }
._ats_picker_card._ats_active {
  border-color: #1565c0; background: linear-gradient(180deg, #fff, #e3f2fd 130%);
  box-shadow: inset 3px 0 0 #1565c0;
}
._ats_picker_card_name { font: 800 11px/1.2 Inter, sans-serif; color: #0f172a; }
._ats_picker_card_meta { font-size: 9px; color: #64748b; margin-top: 2px; }

._ats_picker_footer {
  display: flex; gap: 6px; margin-top: 8px;
}
._ats_picker_footer button { flex: 1; padding: 7px; font-size: 9px; }

/* ─── Section blocks ─────────────────────────────────────────────── */
._ats_section {
  background: #fff;
  border-bottom: 1px solid #e2e8f0;
  padding: 12px 14px;
}
._ats_section_head {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 8px;
}
._ats_section_title {
  font: 800 9px/1 Inter, sans-serif; text-transform: uppercase;
  letter-spacing: 0.6px; color: #475569;
}
._ats_section_hint {
  font-size: 10px; color: #64748b; line-height: 1.4;
  margin-bottom: 8px;
}

._ats_grid_2 {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 6px;
}
._ats_actionbar {
  display: flex; flex-direction: column; gap: 6px;
}
._ats_actionbar ._ats_btn { width: 100%; justify-content: center; padding: 8px; }

/* ─── Insert logic — placeholder + conditional pickers ───────────── */
._ats_logic_row {
  display: grid; grid-template-columns: 1fr auto;
  gap: 6px; margin-bottom: 6px;
}
._ats_logic_row input,
._ats_logic_row select {
  padding: 6px 8px; font-size: 11px;
  border: 1px solid #cbd5e1; outline: none;
  box-sizing: border-box; background: #fff;
}
._ats_logic_row input:focus,
._ats_logic_row select:focus { border-color: #1565c0; }
._ats_logic_row input { font-family: ui-monospace, Consolas, monospace; }

._ats_quick_tags {
  display: flex; flex-wrap: wrap; gap: 4px;
  margin-top: 6px;
}
._ats_quick_tag {
  padding: 3px 7px; font: 700 9px/1 ui-monospace, Consolas, monospace;
  background: #ede9fe; color: #6d28d9; cursor: pointer;
  transition: filter 0.15s;
}
._ats_quick_tag:hover { filter: brightness(0.95); }

/* ─── Detected tags ─────────────────────────────────────────────── */
._ats_detected {
  padding: 10px 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  min-height: 40px;
}
._ats_detected_head {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 6px;
}
._ats_detected_count {
  background: #1565c0; color: #fff; padding: 2px 7px;
  font: 800 9px/1 Inter, sans-serif; border-radius: 100px;
}
._ats_detected_empty {
  font-size: 10px; color: #94a3b8; font-style: italic;
}

/* ─── Mock values ───────────────────────────────────────────────── */
._ats_mocklist {
  display: flex; flex-direction: column;
  gap: 4px; max-height: 280px; overflow-y: auto;
}
._ats_mockrow {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr);
  gap: 4px; align-items: center;
}
._ats_mockrow_label {
  font: 700 10px/1 ui-monospace, Consolas, monospace;
  color: #6d28d9; padding: 5px 7px;
  background: #ede9fe; overflow: hidden;
  text-overflow: ellipsis; white-space: nowrap;
}
._ats_mockrow input {
  padding: 5px 7px; font-size: 11px;
  border: 1px solid #cbd5e1; outline: none;
  box-sizing: border-box;
}
._ats_mockrow input:focus { border-color: #1565c0; }

._ats_metaedit {
  display: grid; grid-template-columns: 1fr 1fr; gap: 8px;
}
._ats_field_label {
  font: 700 8px/1 Inter, sans-serif; text-transform: uppercase;
  letter-spacing: 0.5px; color: #64748b; margin-bottom: 3px;
}
._ats_input, ._ats_select {
  width: 100%; padding: 6px 8px; font-size: 11px;
  border: 1px solid #cbd5e1; outline: none;
  background: #fff; box-sizing: border-box;
  transition: border-color 0.15s;
}
._ats_input:focus, ._ats_select:focus { border-color: #1565c0; }

._ats_empty_state {
  padding: 40px 20px; text-align: center; color: #94a3b8;
  background: #fff;
}
._ats_empty_icon { font-size: 48px; opacity: 0.4; margin-bottom: 10px; }
._ats_empty_title { font-size: 13px; font-weight: 700; color: #475569; margin-bottom: 4px; }
._ats_empty_sub { font-size: 11px; }

._ats_toast_msg {
  font-size: 10px; color: #475569;
  padding: 4px 0; font-style: italic;
}

/* ─── Logic block tree ──────────────────────────────────────────── */
._ats_logic_tree {
  display: flex; flex-direction: column;
  gap: 4px;
  border: 1px solid #e2e8f0;
  background: #fafbfc;
  padding: 8px;
  min-height: 40px;
}
._ats_logic_block {
  border-left: 3px solid #1565c0;
  background: #fff;
  padding: 6px 8px;
  font-size: 11px;
}
._ats_logic_block._ats_logic_warn { border-left-color: #f59e0b; }
._ats_logic_block._ats_logic_err  { border-left-color: #dc2626; background: #fef2f2; }

._ats_logic_block_head {
  display: flex; align-items: center; gap: 6px;
  flex-wrap: wrap;
}
._ats_logic_block_kind {
  font: 800 9px/1 Inter, sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #475569;
}
._ats_logic_block_cond {
  font: 700 11px/1 ui-monospace, Consolas, monospace;
  background: #ede9fe; color: #6d28d9;
  border: none; padding: 3px 7px;
  cursor: pointer;
  transition: filter 0.15s;
}
._ats_logic_block_cond:hover { filter: brightness(0.95); }
._ats_logic_block_lines {
  font: 700 9px/1 ui-monospace, Consolas, monospace;
  color: #94a3b8;
  margin-left: auto;
}
._ats_logic_block_err {
  font-size: 10px; color: #b91c1c;
  margin-top: 4px;
  font-weight: 600;
}
._ats_logic_children {
  margin-top: 4px;
  display: flex; flex-direction: column;
  gap: 4px;
}

/* ─── Template prompts (typed, schema-driven) ──────────────────── */
._ats_promptlist {
  display: flex; flex-direction: column;
  gap: 8px;
  max-height: 420px; overflow-y: auto;
  padding-right: 2px;
}
._ats_promptrow {
  border: 1px solid #e2e8f0;
  background: #fff;
  padding: 8px;
}
._ats_promptrow_head {
  display: flex; align-items: center;
  gap: 6px;
  margin-bottom: 6px;
  flex-wrap: wrap;
}
._ats_promptrow_chip {
  font: 700 10px/1 ui-monospace, Consolas, monospace;
  background: #ede9fe; color: #6d28d9;
  border: none; padding: 4px 8px;
  cursor: pointer;
  max-width: 50%;
  overflow: hidden; text-overflow: ellipsis;
  white-space: nowrap;
  transition: filter 0.15s;
}
._ats_promptrow_chip:hover { filter: brightness(0.95); }
._ats_promptrow_label {
  font: 700 10px/1.2 Inter, sans-serif;
  color: #475569;
  flex: 1; min-width: 0;
  overflow: hidden; text-overflow: ellipsis;
  white-space: nowrap;
}
._ats_promptrow_type {
  font: 800 8px/1 Inter, sans-serif;
  letter-spacing: 0.5px; text-transform: uppercase;
  background: #f1f5f9; color: #475569;
  padding: 3px 6px;
}
._ats_promptrow_cog {
  padding: 4px 7px !important;
  font-size: 11px !important;
  line-height: 1 !important;
}
._ats_textarea {
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  resize: vertical;
  min-height: 50px;
}

._ats_schema_editor {
  margin-top: 8px; padding: 10px;
  background: linear-gradient(180deg, #fffbeb 0%, #fef3c7 130%);
  border: 1px solid #fcd34d;
}
._ats_schema_editor_head {
  font: 800 9px/1 Inter, sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #92400e;
  margin-bottom: 8px;
}
._ats_schema_editor_head code {
  font: 700 10px/1 ui-monospace, Consolas, monospace;
  background: rgba(255,255,255,0.6); padding: 1px 5px;
  color: #6d28d9;
}
._ats_schema_grid {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 8px; margin-bottom: 6px;
}
._ats_schema_field { min-width: 0; }
._ats_schema_editor > ._ats_schema_field + ._ats_schema_field { margin-top: 6px; }
._ats_schema_editor > ._ats_schema_grid + ._ats_schema_field { margin-top: 6px; }
